"""Generate a selectable, linked three-page A4 resume from shared JSON data."""
import json,html
from pathlib import Path
from playwright.sync_api import sync_playwright
root=Path(__file__).resolve().parent.parent
p=json.loads((root/'src/profile.json').read_text())
projects=json.loads((root/'src/projects.json').read_text())
e=html.escape
style='''@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;color:#20251f;font-size:10pt;line-height:1.5}.page{width:210mm;height:297mm;padding:19mm 19mm 17mm;position:relative;break-after:page}.page:last-child{break-after:auto}h1{font-size:32pt;line-height:1.1;font-weight:500;margin:14px 0}h2{font-size:19pt;font-weight:500;margin:25px 0 13px}h3{font-size:12pt;margin:0 0 7px;font-weight:600}p{margin:6px 0 12px}.eyebrow{font-size:8pt;letter-spacing:1.5px;color:#385c44}.role{font-size:13pt;color:#385c44}a{color:#385c44;text-decoration:none}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.skills>div{border-top:1px solid #dcded5;padding-top:12px}.muted{color:#6d7269}.project{border-top:1px solid #dcded5;margin:13px 0;padding-top:12px}.project p{font-size:9.5pt}.footer{position:absolute;bottom:13mm;left:19mm;right:19mm;display:flex;justify-content:space-between;border-top:1px solid #dcded5;padding-top:8px;font-size:8pt}.contacts{margin:17px 0;padding:13px 0;border-top:1px solid #dcded5;border-bottom:1px solid #dcded5}'''
def footer(n):return f'<div class="footer"><a href="{e(p["portfolio"])}">Полное веб-портфолио ↗</a><span>Михаил Потапов · {n} / 3</span></div>'
def project(x):return f'<div class="project"><span class="eyebrow">{x["year"]} · {e(x["platforms"])}</span><h3>{e(x["title"])}</h3><p>{e(x["about"])}</p><p><b>Личный вклад:</b> {e(x["contribution"])}</p></div>'
content=f'''<!doctype html><html lang="ru"><meta charset="utf-8"><title>Михаил Потапов — резюме</title><style>{style}</style><body><section class="page"><span class="eyebrow">ПРОФЕССИОНАЛЬНОЕ РЕЗЮМЕ</span><h1>{e(p['name'])}</h1><p class="role">{e(p['role'])}</p><p>{e(p['intro'])}</p><div class="contacts"><a href="{p['telegram']}">Telegram: @Bleeerr</a> · <a href="mailto:{p['email']}">{p['email']}</a><br><a href="{p['phoneLink']}">{p['phone']}</a> · {e(p['location'])} · {e(p['workFormat'])}</div><h2>Техническая экспертиза</h2><div class="grid skills">{''.join(f'<div><h3>{e(s["title"])}</h3><p>{e(s["text"])}</p></div>' for s in p['skills'])}</div><h2>Профессиональный путь</h2><p>{e(p['history'])} С 2022 года — соучредитель MIDcore; продолжаю писать код и руководить программистами.</p><p class="muted">Lead Unity Developer / Technical Lead. Полная занятость; рассмотрю проектную работу.</p>{footer(1)}</section><section class="page"><span class="eyebrow">ЛИЧНЫЙ ВКЛАД И ТЕХНИЧЕСКОЕ РУКОВОДСТВО</span><h2>Архитектура и команда</h2><p>{e(' '.join(item['text'] for item in p['leadership']))}</p><div class="achievements">{''.join(f'<p><b>{e(a["title"])}.</b> {e(a["solution"])} {e(a["result"])}</p>' for a in p['achievements'])}</div><h2>Инженерная практика</h2><p>ООП, ECS, Dependency Injection, Object Pool, FSM и Event Bus. Frame Debugger, Memory Profiler, Addressables, Garbage Collector. Аудит legacy-кода с ИИ и инструменты Unity Editor.</p>{footer(2)}</section><section class="page"><span class="eyebrow">ИЗБРАННЫЕ ПРОЕКТЫ</span><h2>Игры и личное участие</h2>{project(projects[0])}{project(projects[5])}{project(projects[6])}<h2>Другие проекты · 2011–2025</h2><p>MemeBattle, «А ты шаришь!», Tournament Mode, Monsters Crush Clicker, Tanktoon, Wordica, FlipStone, WordBox, UniFight и UniCross.</p><p>Разработка игрового клиента, программирование UI и уровней, взаимодействие с серверной частью, техническая реализация проектов, созданных совместно с партнёрами.</p><h2>Контакты</h2><p><a href="{p['telegram']}">Telegram ↗</a> · <a href="mailto:{p['email']}">{p['email']}</a><br><a href="{p['phoneLink']}">{p['phone']}</a></p><p><a href="{p['portfolio']}">{p['portfolio']}</a></p>{footer(3)}</section></body></html>'''
(root/'public/resume-print.html').write_text(content)
with sync_playwright() as pw:
 browser=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 page=browser.new_page();page.set_content(content)
 for section in page.locator('.page').all():
  assert section.evaluate('(e)=>e.scrollHeight <= e.clientHeight'), 'PDF page overflow'
 page.pdf(path=str(root/'public/resume.pdf'),format='A4',print_background=True,prefer_css_page_size=True)
 browser.close()
print('Created public/resume.pdf (3 A4 pages) and resume-print.html')
